const ctx = $input.first().json.ctx;
const DASH = 'http://51.142.158.234:3030/#';
const ex = ctx.exposure || {};
const n = (x) => Number(x) || 0;
const lines = [':sunrise: *Morning Chloe - portfolio risk brief*'];
lines.push(':bar_chart: *Exposure right now:* ' + n(ex.total) + ' open risk' + (n(ex.total) === 1 ? '' : 's') + ' across ' + n(ex.accounts) + ' account' + (n(ex.accounts) === 1 ? '' : 's') + ' - ' + n(ex.critical) + ' critical, ' + n(ex.high) + ' high.');
const fk = ctx.for_katie || [];
if (fk.length) {
  lines.push(':clipboard: *Worth carrying to Katie* (critical band' + ((ctx.register_high || []).length ? ' + register Level 4+' : '') + '):');
  for (const r of fk) {
    lines.push('  :red_circle: ' + r.summary + (r.account ? '  _(' + r.account + ')_' : '') + (r.raised_by ? ' - raised by ' + r.raised_by : ''));
    lines.push('      <' + DASH + '/partner?signal=' + r.id + '|Open on the dashboard ->');
  }
} else {
  lines.push(':clipboard: Nothing at Katie level this week - no critical-band risks open.');
}
for (const r of (ctx.register_high || [])) {
  lines.push('  :rotating_light: ' + r.name + ' - ' + r.escalation + (r.account ? '  _(' + r.account + ')_' : '') + ' (on the register)' + (r.account_id ? '  <' + DASH + '/partner?account=' + r.account_id + '|Open ->' : ''));
}
lines.push(':triangular_flag_on_post: ' + n(ctx.week_new) + ' new risk' + (n(ctx.week_new) === 1 ? '' : 's') + ' surfaced this week.');
if (n(ctx.unpushed) > 0) lines.push(':memo: *Register hygiene:* ' + n(ctx.unpushed) + ' serious risk' + (n(ctx.unpushed) === 1 ? ' is' : 's are') + ' flagged by tnAI but not yet on the Monday register - one tap each on <' + DASH + '/partner|the dashboard> to push.');
lines.push('_Ask me anything: "what is our exposure on HMRC?", "prep me for the Katie meeting"._');
return [{ json: { email: 'chloe.hollinshead@tecknuovo.com', text: lines.join('\n') } }];
